import re, os, sys

def find_functions(filepath):
    with open(filepath) as f:
        lines = f.readlines()

    functions = []
    current_func = None
    brace_count = 0
    start_line = 0

    for i, line in enumerate(lines, 1):
        stripped = line.strip()

        # Detect function/method definitions
        func_match = re.match(r'^(\s*)(async\s+)?(function\s+|export\s+(async\s+)?function\s+|(\w+\s*\([^)]*\)\s*{|[a-zA-Z_]\w*\s*\([^)]*\)\s*{|async\s+[a-zA-Z_]\w*\s*\([^)]*\)\s*{))', stripped)
        method_match = re.match(r'^\s*(async\s+)?\w+\s*\([^)]*\)\s*{', stripped)

        if current_func:
            brace_count += stripped.count('{') - stripped.count('}')
            if brace_count <= 0:
                line_count = i - start_line + 1
                if line_count > 200:
                    functions.append((current_func, start_line, line_count))
                current_func = None

        # Start new function
        if not current_func:
            # Match 'function name' or 'name = function' or 'method(...) {'
            fn = None
            m = re.search(r'(?:function\s+(\w+)|(\w+)\s*=\s*(?:async\s+)?function|\bclass\s+(\w+))', stripped)
            if m:
                fn = m.group(1) or m.group(2) or m.group(3)

            # Check for class boundary
            if fn and stripped.startswith('class'):
                current_func = fn
                brace_count = stripped.count('{') - stripped.count('}')
                start_line = i
                continue

            # Check for methods
            is_method = bool(re.match(r'^\s*(?:async\s+)?\w+\s*\(', stripped) and stripped.rstrip().endswith('{'))
            if is_method and 'function' in stripped or (is_method and not stripped.startswith('if') and not stripped.startswith('for') and not stripped.startswith('while')):
                # Get method name
                mm = re.match(r'^\s*(?:async\s+)?(\w+)\s*\(', stripped)
                if mm:
                    fn = mm.group(1)

            if fn and ('{' in stripped):
                current_func = fn
                brace_count = 1
                start_line = i

    return functions

for fname in sorted(os.listdir('src/core')):
    if not fname.endswith('.ts') or fname == 'README.md':
        continue
    fpath = 'src/core/' + fname
    funcs = find_functions(fpath)
    for name, line, count in funcs:
        print(f'{fpath}:{line} — {name} ({count} lines)')
